using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;
namespace MapSharedProps.EditorTools {
// Optional presentation only: malformed data falls back without affecting the legacy root.
public sealed class ChestSanctumBuilder {
 [Serializable]public class Group {public string kind;public float[] positions,normals,uv,tangents;public int[] triangles;}
 [Serializable]public class Descriptor {public int version,motes,lightsPerChest,maxActiveLights;public string id,assetKey,axes,normalSource,crystalMode;public Group[] groups;}
 readonly Descriptor data;readonly Texture2D normal,packed;readonly bool mapped;readonly Dictionary<string,Mesh> meshes=new Dictionary<string,Mesh>();
 static readonly string[] Kinds={"body","relief","crystal","support"};
 static void Check(bool value,string why){if(!value)throw new InvalidDataException("Rainbow sanctum: "+why);}
 static bool Finite(float x)=>!float.IsNaN(x)&&!float.IsInfinity(x);
 static void Floats(float[] a,int count,float limit){Check(a!=null&&a.Length==count&&Array.TrueForAll(a,x=>Finite(x)&&Mathf.Abs(x)<=limit),"array");}
 public static bool Valid(Descriptor d){if(d==null)return false;try{Check(d.version==1&&d.id=="rainbow-sanctum-v1"&&d.assetKey=="tdj/treasurechest_rainbow"&&d.axes=="Unity X/Y/Z"&&d.motes==36&&d.lightsPerChest==3&&d.maxActiveLights==6&&d.normalSource=="gold-royal-relief-v1"&&d.crystalMode=="opaque-prismatic-depth-v1","identity");Check(d.groups!=null&&d.groups.Length==4,"groups");var seen=new HashSet<string>();int total=0;foreach(var g in d.groups){Check(g!=null&&Array.IndexOf(Kinds,g.kind)>=0&&seen.Add(g.kind)&&g.positions!=null&&g.positions.Length%3==0,"group");int n=g.positions.Length/3;Check(n>=3&&n<=30000,"vertices");total+=n;Floats(g.positions,n*3,2);Floats(g.normals,n*3,1.01f);Floats(g.uv,n*2,1);Floats(g.tangents,n*4,1.01f);for(int i=0;i<n;i++){Check(Mathf.Abs(new Vector3(g.normals[i*3],g.normals[i*3+1],g.normals[i*3+2]).magnitude-1)<.02f&&Mathf.Abs(new Vector3(g.tangents[i*4],g.tangents[i*4+1],g.tangents[i*4+2]).magnitude-1)<.02f&&Mathf.Abs(g.tangents[i*4+3])==1,"TBN");}Check(g.triangles!=null&&g.triangles.Length>0&&g.triangles.Length%3==0&&g.triangles.Length<=90000&&Array.TrueForAll(g.triangles,x=>x>=0&&x<n),"indices");}Check(total<=30000,"budget");return true;}catch(InvalidDataException e){Debug.LogWarning(e.Message+"; keeping legacy rainbow.");return false;}}
 public ChestSanctumBuilder(SmallPropsV1.Data all){var d=all.chestSurfacesV1?.sanctumV1;if(!Valid(d))return;data=d;var maps=all.chestSurfacesV1.royalReliefV1;try{if(maps!=null&&maps.version==1&&maps.normal!=null&&maps.ao!=null){normal=ChestRoyalLitBuilder.Normal(Convert.FromBase64String(maps.normal.png));packed=ChestRoyalLitBuilder.Packed(Convert.FromBase64String(maps.ao.png));mapped=true;}}catch(Exception e){Debug.LogWarning("Rainbow relief maps unavailable; using flat relief material: "+e.Message);}}
 public bool Apply(GameObject root,string id,string folder){if(data==null||id!="treasurechest_rainbow")return false;var shader=Shader.Find("MapSharedProps/ChestSanctum");if(!shader||!shader.isSupported){Debug.LogWarning("Rainbow shader unavailable; keeping legacy presentation.");return false;}var group=new GameObject("Prismatic sanctum");group.transform.SetParent(root.transform,false);var renderers=new List<Renderer>();foreach(var g in data.groups){var mesh=SmallPropsV1.MeshOf(g.positions,g.normals,Enumerable.Repeat(1f,g.positions.Length).ToArray(),g.triangles);mesh.uv=Enumerable.Range(0,g.uv.Length/2).Select(i=>new Vector2(g.uv[i*2],g.uv[i*2+1])).ToArray();mesh.tangents=Enumerable.Range(0,g.tangents.Length/4).Select(i=>new Vector4(g.tangents[i*4],g.tangents[i*4+1],g.tangents[i*4+2],g.tangents[i*4+3])).ToArray();mesh=SharedImportCache.StoreMesh(mesh,"sanctum-v1/"+JsonUtility.ToJson(g));var mat=new Material(shader){name="Prismatic "+g.kind,enableInstancing=true};mat.SetFloat("_Relief",g.kind=="relief"?1:0);mat.SetFloat("_Crystal",g.kind=="crystal"?1:0);mat.SetFloat("_Support",g.kind=="support"?1:0);mat.SetFloat("_UseMaps",mapped?1:0);mat.SetFloat("_ChestTime",-1);if(mapped){mat.SetTexture("_Normal",normal);mat.SetTexture("_Mask",packed);}string path=folder+"/sanctum-"+g.kind+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){EditorUtility.CopySerialized(mat,old);UnityEngine.Object.DestroyImmediate(mat);mat=old;}else AssetDatabase.CreateAsset(mat,path);var o=new GameObject(g.kind);o.transform.SetParent(group.transform,false);o.AddComponent<MeshFilter>().sharedMesh=mesh;var r=o.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;r.probeAnchor=root.transform;r.shadowCastingMode=ShadowCastingMode.On;renderers.Add(r);}
 var fx=new GameObject("Prismatic motes");fx.transform.SetParent(group.transform,false);fx.AddComponent<MeshFilter>().sharedMesh=EffectMesh();var fr=fx.AddComponent<MeshRenderer>();var fmat=new Material(Shader.Find("MapSharedProps/ChestFx")){name="Prismatic motes",enableInstancing=true};var fp=folder+"/sanctum-fx.mat";var previous=AssetDatabase.LoadAssetAtPath<Material>(fp);if(previous){UnityEngine.Object.DestroyImmediate(fmat);fmat=previous;}else AssetDatabase.CreateAsset(fmat,fp);fr.sharedMaterial=fmat;fr.shadowCastingMode=ShadowCastingMode.Off;fr.receiveShadows=false;
 root.GetComponent<Renderer>().enabled=false;foreach(string name in new[]{"Side relief","Bounded seam light and motes"}){var child=root.transform.Find(name);if(child)child.gameObject.SetActive(false);}var legacy=root.GetComponent<MapSharedProps.ChestPresentation>();if(legacy)legacy.enabled=false;root.AddComponent<MapSharedProps.ChestSanctumPresentation>().Configure(renderers.ToArray(),fr);return true;}
 static Mesh EffectMesh(){var p=new List<Vector3>();var uv=new List<Vector2>();var start=new List<Vector4>();var end=new List<Vector4>();var shape=new List<Vector4>();var colors=new List<Color>();var ix=new List<int>();for(int k=0;k<36;k++){float a=k*2.399f,w=.11f+(k%4)*.016f;int n=p.Count;Color c=Color.HSVToRGB(k/36f,.857142857f,1.9f,true);for(int j=0;j<4;j++){p.Add(new Vector3(j%2-.5f,j/2-.5f,0));uv.Add(new Vector2(j%2,j/2));start.Add(new Vector4(Mathf.Cos(a)*(.4f+k%3*.08f),.4f+k%9*.071f,Mathf.Sin(a)*.35f,0));end.Add(new Vector4(0,0,0,(k*.6180339f)%1));shape.Add(new Vector4(w,w,0,0));colors.Add(new Color(c.r,c.g,c.b,.64f));}ix.AddRange(new[]{n,n+2,n+1,n+1,n+2,n+3});}var mesh=new Mesh{name="Prismatic 36 motes"};mesh.SetVertices(p);mesh.SetUVs(0,uv);mesh.SetUVs(1,start);mesh.SetUVs(2,end);mesh.SetUVs(3,shape);mesh.SetColors(colors);mesh.SetTriangles(ix,0);mesh.bounds=new Bounds(new Vector3(0,.7f,0),new Vector3(2,2,2));return SharedImportCache.StoreMesh(mesh,"sanctum-motes-v1/36");}
}
}
